-- Parse a raw GKG record into article metadata and record any fields that cannot be normalized.
CREATE OR REPLACE FUNCTION `${dataset}.gkg_parse_source_v01`(raw_json STRING)
RETURNS STRUCT<gkg_record_id STRING,gkg_date STRING,source_collection STRING,source_name STRING,
 document_url STRING,title STRING,themes ARRAY<STRING>,persons ARRAY<STRING>,organizations ARRAY<STRING>,locations ARRAY<STRING>,
