// Count UTF-8 bytes so the size limit also holds for non-ASCII source text.
function utf8bytes(value) {
  var n=0;
  for (var i=0;i<value.length;i++) {
    var c=value.charCodeAt(i);
    if(c<128)n++; else if(c<2048)n+=2;
    else if(c>=0xD800&&c<=0xDBFF&&i+1<value.length&&value.charCodeAt(i+1)>=0xDC00&&value.charCodeAt(i+1)<=0xDFFF){n+=4;i++;}
    else n+=3;
  }
  return n;
}
var whitespace=/[\u0009-\u000D\u001C-\u0020\u0085\u00A0\u1680\u2000-\u200A\u2028\u2029\u202F\u205F\u3000]+/g;
// Trim the whitespace characters recognized by the source normalizer.
function strip(s){return s.replace(/^[\u0009-\u000D\u001C-\u0020\u0085\u00A0\u1680\u2000-\u200A\u2028\u2029\u202F\u205F\u3000]+|[\u0009-\u000D\u001C-\u0020\u0085\u00A0\u1680\u2000-\u200A\u2028\u2029\u202F\u205F\u3000]+$/g,"");}
// Reduce each run of whitespace to a single space and trim the result.
function collapse(s){return strip(s.replace(whitespace," "));}
// Read an optional GKG text field and reject unexpected field types.
function stringValue(v){if(v===null||v===undefined)return ""; if(typeof v!=="string")throw Error("named source values must be strings or null");return v;}
// Convert a Unicode code point to its JavaScript string representation.
