function sep(i){return i===0?" ":"; ";}
// Assemble the nonempty metadata fields into the text sent for embedding.
function text(v){var a=[];for(var i=0;i<5;i++)if(v[i])a.push(names[i]+": "+v[i]);return a.join("\n");}
for(var i=0;i<5;i++)values[i]=units[i].join(sep(i));
var original=text(values),originalBytes=bytes(original);
if(originalBytes<=6000){for(var i=0;i<5;i++)counts[i]=units[i].length;}
else {
 for(var i=0;i<5;i++){var n=0;while(counts[i]<units[i].length){var cost=bytes(units[i][counts[i]])+(counts[i]?sep(i).length:0);if(n+cost>reserves[i])break;n+=cost;counts[i]++;}values[i]=units[i].slice(0,counts[i]).join(sep(i));}
 var used=bytes(text(values)),progress=true;
 while(progress){progress=false;for(var i=0;i<5;i++){if(counts[i]===units[i].length)continue;var unit=units[i][counts[i]],prefix=counts[i]?sep(i):names[i]+": ";var cost=bytes(prefix+unit)+(!counts[i]&&used?1:0);if(used+cost<=6000){values[i]+=(counts[i]?sep(i):"")+unit;counts[i]++;used+=cost;progress=true;}}}
}
var result=text(values),truncated=[],omitted={};for(var i=0;i<5;i++){omitted[names[i]]=units[i].length-counts[i];if(omitted[names[i]])truncated.push(names[i]);}
if(bytes(result)>6000)throw Error("metadata UTF-8 budget exceeded");
return {metadata_text:result,title:values[0],themes:units[1].slice(0,counts[1]),persons:units[2].slice(0,counts[2]),organizations:units[3].slice(0,counts[3]),locations:units[4].slice(0,counts[4]),
 truncation_json:JSON.stringify({maximum_utf8_bytes:6000,original_utf8_bytes:originalBytes,retained_utf8_bytes:bytes(result),truncated_fields:truncated,omitted_units:omitted,policy:"full_if_total_fits_else_balanced_complete_label_prefixes_with_redistribution"})};
''';
